 36→      'DECRYPTION_FAILED'
 37→    );
 38→  }
 39→
 40→  const obj = entry as Record<string, unknown>;
 41→
 42→  if (typeof obj.cid !== 'string') {
 43→    throw new CryptoError(
 44→      `Invalid file metadata format: versions[${index}].cid must be string`,
 45→      'DECRYPTION_FAILED'
 46→    );
 47→  }
 48→  if (typeof obj.fileKeyEncrypted !== 'string') {
 49→    throw new CryptoError(
 50→      `Invalid file metadata format: versions[${index}].fileKeyEncrypted must be string`,
 51→      'DECRYPTION_FAILED'
 52→    );
 53→  }
 54→  if (typeof obj.fileIv !== 'string') {
 55→    throw new CryptoError(
 56→      `Invalid file metadata format: versions[${index}].fileIv must be string`,
 57→      'DECRYPTION_FAILED'
 58→    );
 59→  }
 60→  if (typeof obj.size !== 'number') {
 61→    throw new CryptoError(
 62→      `Invalid file metadata format: versions[${index}].size must be number`,
 63→      'DECRYPTION_FAILED'
 64→    );
 65→  }
 66→  if (typeof obj.timestamp !== 'number') {
 67→    throw new CryptoError(
 68→      `Invalid file metadata format: versions[${index}].timestamp must be number`,
 69→      'DECRYPTION_FAILED'
 70→    );
 71→  }
 72→  if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
 73→    throw new CryptoError(
