218→/**
219→ * Decrypts file metadata encrypted with AES-256-GCM.
220→ *
221→ * @param encrypted - Encrypted metadata with IV (hex) and ciphertext (base64)
222→ * @param folderKey - 32-byte AES key of the parent folder
223→ * @returns Decrypted file metadata object
224→ * @throws CryptoError if decryption fails (wrong key, corrupted data, etc.)
225→ */
226→export async function decryptFileMetadata(
227→  encrypted: EncryptedFileMetadata,
228→  folderKey: Uint8Array
229→): Promise<FileMetadata> {
230→  // Decode IV and ciphertext
231→  const iv = hexToBytes(encrypted.iv);
232→  const ciphertext = Uint8Array.from(atob(encrypted.data), (c) => c.charCodeAt(0));
233→
234→  // Decrypt with AES-256-GCM
235→  const plaintext = await decryptAesGcm(ciphertext, folderKey, iv);
236→
237→  // Parse JSON back to metadata object
238→  // [SECURITY: MEDIUM-07] Validate the decrypted data before returning
239→  let parsed: unknown;
240→  try {
241→    parsed = JSON.parse(new TextDecoder().decode(plaintext));
242→  } catch {
243→    throw new CryptoError('Invalid file metadata format: not valid JSON', 'DECRYPTION_FAILED');
244→  }
245→  return validateFileMetadata(parsed);
246→}
