333→        let now = SystemTime::now();
334→
335→        fs.inodes.remove(child_ino);
336→
337→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
338→            parent_inode.attr.mtime = now;
339→            parent_inode.attr.ctime = now;
