361→            } else {
362→                let parent_path = build_folder_path(fs, parent);
363→
364→                let bin_entry = crate::crypto::bin::BinEntry {
365→                    id: crate::crypto::utils::generate_uuid_v4(),
366→                    item_type: crate::crypto::bin::BinItemType::File,
367→                    name: item_name.clone(),
368→                    original_parent_ipns_name: parent_ipns_name,
369→                    original_path: parent_path,
370→                    deleted_at: now
