380→                crate::fuse::spawn_bin_entry_publish(
381→                    fs.api.clone(),
382→                    fs.rt.clone(),
383→                    bin_entry,
384→                    fs.private_key.clone(),
385→                    fs.public_key.to_vec(),
386→                    fs.publish_coordinator.clone(),
